31	
32	function mixHex(background: string, foreground: string, foregroundWeight: number): string {
33	  const channels = (value: string) => [1, 3, 5].map((offset) => Number.parseInt(value.slice(offset, offset + 2), 16));
34	  const base = channels(background);
35	  const overlay = channels(foreground);
36	  return `#${base.map((channel, index) => Math.round(channel * (1 - foregroundWeight) + overlay[index]! * foregroundWeight)
37	    .toString(16)
38	    .padStart(2, "0")).join("")}`;
39	}
40	
41	/** Native state roles projected from the browser- and terminal-neutral contract. */
42	export function projectNativeTheme(name: NativeThemeName): NativeTheme {
43	  const colors = keatingDesignContract.themes[name].colors;
44	  const selectedSurface = mixHex(colors.surfaceRaised, colors.accent, name === "dark" ? 0.12 : 0.08);
45	  const pressedSurface = mixHex(colors.surfaceRaised, colors.accent, name === "dark" ? 0.22 : 0.15);
46	  const dangerSurface = mixHex(colors.surfaceMuted, colors.danger, name === "dark" ? 0.18 : 0.1);
47	  return {
48	    name,
49	    colors: {
50	      background: colors.surface,
51	      backgroundDeep: colors.surfaceMuted,
52	      surface: colors.surfaceRaised,
53	      surfaceRaised: selectedSurface,
54	      surfacePressed: pressedSurface,
55	      text: colors.text,
56	      textMuted: colors.mutedText,
57	      textFaint: colors.mutedText,
58	      primary: colors.accent,
59	      primaryStrong: colors.accentText === colors.accent
60	        ? mixHex(colors.accent, colors.onAccent, 0.25)
61	        : colors.accentText,
62	      primaryInk: colors.onAccent,
63	      border: colors.border,
64	      borderStrong: colors.border,
65	      error: colors.danger,
66	      errorSurface: dangerSurface,
67	      warning: colors.warning,
68	      success: colors.success,
69	      info: colors.info,
70	      userBubble: mixHex(colors.surfaceMuted, colors.accent, name === "dark" ? 0.14 : 0.08),
71	      overlay: name === "dark" ? "rgba(0, 0, 0, 0.72)" : "rgba(28, 33, 27, 0.28)",
72	    },
73	    statusBarStyle: name === "dark" ? "light" : "dark",
74	  };
75	}
